import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        int[] temps = {12, 15, 11, 19, 17, 24, 20};
        int[] steps = {4000, 6500, 3200, 8000, 5100};

        int largestRise = Integer.MIN_VALUE;
        for (int i = 1; i < temps.length; i++) {
            int rise = temps[i] - temps[i - 1];
            if (rise > largestRise) {
                largestRise = rise;
            }
        }

        int[] totals = new int[steps.length];
        totals[0] = steps[0];
        for (int i = 1; i < steps.length; i++) {
            totals[i] = totals[i - 1] + steps[i];
        }

        System.out.println("Largest rise: " + largestRise);
        System.out.println("Step totals: " + Arrays.toString(totals));
    }
}
